# Hypothesis: keep minority cells that are "deep" inside a component (>=3 same-color 4-neighbors or enclosed); drop boundary cells touching bg.
def comps(g,bg):
    seen=set(); out=[]
    h,w=len(g),len(g[0])
    for i in range(h):
        for j in range(w):
            if g[i][j]!=bg and (i,j) not in seen:
                stack=[(i,j)]; seen.add((i,j)); c=[]
                while stack:
                    y,x=stack.pop(); c.append((y,x))
                    for dy,dx in ((1,0),(-1,0),(0,1),(0,-1)):
                        ny,nx=y+dy,x+dx
                        if 0<=ny<h and 0<=nx<w and g[ny][nx]!=bg and (ny,nx) not in seen:
                            seen.add((ny,nx)); stack.append((ny,nx))
                out.append(c)
    return out
for n,(gi,go) in pairs.items():
    bgc=Counter(x for r in gi for x in r).most_common(1)[0][0]
